<?php
session_start(); if(!isset($_SESSION['divisi'])||$_SESSION['divisi']!=='akunting'){header('Location: ../index.php');exit;} require_once '../config/database.php';
$bulan=$_GET['bulan']??date('Y-m'); if(!preg_match('/^\d{4}-\d{2}$/',$bulan))$bulan=date('Y-m'); [$y,$m]=array_map('intval',explode('-',$bulan)); $start=sprintf('%04d-%02d-01',$y,$m); $next=date('Y-m-d',strtotime($start.' +1 month'));
$st=$pdo->prepare("SELECT l.id,l.waktu_mulai,l.waktu_selesai,l.tarif_per_jam,l.durasi_jam,l.total_upah_lembur,k.nama_lengkap,k.barcode_uid,a.username FROM absensi_lembur l LEFT JOIN karyawan k ON l.karyawan_id=k.id LEFT JOIN admin_users a ON l.admin_id=a.id WHERE l.waktu_mulai >= ?::date AND l.waktu_mulai < ?::date ORDER BY l.waktu_mulai DESC");$st->execute([$start,$next]);$rows=$st->fetchAll();
$totalJam=0;$totalUpah=0;foreach($rows as $r){$totalJam+=(float)$r['durasi_jam'];$totalUpah+=(float)$r['total_upah_lembur'];} function rp($v){return 'Rp '.number_format((float)$v,0,',','.');}
?>
<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Rekap Lembur - Akunting</title><link href="../assets/css/bootstrap.min.css" rel="stylesheet"><style>body{background:#f8f9fa}.sidebar{min-height:100vh;background:#fff;border-right:1px solid #ddd}.brand{color:#198754;font-weight:700}.nav-link{color:#555;border-radius:8px;margin:3px 10px}.nav-link:hover,.nav-link.active{background:#198754;color:#fff}.content{padding:25px}.card{border:0;border-radius:12px}</style></head><body><div class="container-fluid"><div class="row"><aside class="col-md-3 col-lg-2 sidebar p-3"><h5 class="brand mb-4">🍤 Pabrik Udang</h5><small class="text-muted px-2">AKUNTING</small><nav class="mt-2"><a class="nav-link" href="dashboard_akunting.php">Dashboard</a><a class="nav-link" href="rekap_produksi.php">Rekap Produksi</a><a class="nav-link" href="rekap_upah.php">Rekap Upah</a><a class="nav-link" href="histori_produksi_akunting.php">Histori Transaksi</a><a class="nav-link" href="master_tarif.php">Master Tarif</a><a class="nav-link active" href="rekap_lembur.php">Rekap Lembur</a><a class="nav-link" href="profil_akunting.php">Profil Akunting</a><a class="nav-link" href="../logout.php">Logout</a></nav></aside><main class="col-md-9 col-lg-10 content"><div class="d-flex justify-content-between align-items-center mb-4"><div><h3 class="fw-bold">Rekap Lembur</h3><p class="text-muted mb-0">Rekap lembur berdasarkan bulan.</p></div><form><input type="month" name="bulan" value="<?=htmlspecialchars($bulan)?>" class="form-control" onchange="this.form.submit()"></form></div><div class="row g-3 mb-4"><div class="col-md-4"><div class="card shadow-sm p-4"><small class="text-muted">Jumlah Lembur</small><h3 class="mt-2"><?=count($rows)?></h3></div></div><div class="col-md-4"><div class="card shadow-sm p-4"><small class="text-muted">Total Durasi</small><h3 class="mt-2"><?=number_format($totalJam,2,',','.')?> jam</h3></div></div><div class="col-md-4"><div class="card shadow-sm p-4"><small class="text-muted">Total Upah Lembur</small><h3 class="text-success mt-2"><?=rp($totalUpah)?></h3></div></div></div><div class="card shadow-sm"><div class="card-body"><div class="table-responsive"><table class="table table-hover align-middle"><thead class="table-light"><tr><th>Waktu Mulai</th><th>Karyawan</th><th>Selesai</th><th>Durasi</th><th>Tarif/Jam</th><th>Total Upah</th><th>Admin</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?=date('d/m/Y H:i',strtotime($r['waktu_mulai']))?></td><td><b><?=htmlspecialchars($r['nama_lengkap']??'-')?></b><br><small><?=htmlspecialchars($r['barcode_uid']??'-')?></small></td><td><?=$r['waktu_selesai']?date('d/m/Y H:i',strtotime($r['waktu_selesai'])):'-'?></td><td><?=number_format((float)$r['durasi_jam'],2,',','.')?> jam</td><td><?=rp($r['tarif_per_jam'])?></td><td><?=rp($r['total_upah_lembur'])?></td><td><?=htmlspecialchars($r['username']??'-')?></td></tr><?php endforeach;if(!$rows): ?><tr><td colspan="7" class="text-center text-muted py-4">Belum ada data lembur pada bulan ini.</td></tr><?php endif;?></tbody></table></div></div></div></main></div></div></body></html>
